function gp_config_all(): array
{
    static $config = null;
    if (is_array($config)) {
        return $config;
    }

    $defaults = [
        'app' => [
            'name' => 'Mairie de Grand-Popo',
            'url' => '',
            'timezone' => 'Africa/Porto-Novo',
        ],
        'security' => [
            'app_key' => 'change-me-grand-popo-2026',
        ],
        'database' => [
            'path' => GP_DB,
        ],
        'auth' => [
            'session_name' => 'grand_popo_session',
            'session_lifetime' => 86400,
            'admin' => [
                'default_username' => 'admin',
                'default_password' => 'grand-popo',
            ],
        ],
        'forum' => [
            'registration' => [
                'enabled' => true,
                'min_password_length' => 8,
            ],
            'default_redirect' => '/forums-de-discussion',
        ],
        'contact' => [
            'email' => 'contact@mairiegrandpopo.bj',
            'phone' => '+229 0197386269',
            'address' => 'Centre ville Grand-Popo',
        ],
        'mail' => [
            'from_name' => 'Mairie de Grand-Popo',
            'from_email' => 'contact@mairiegrandpopo.bj',
            'smtp_host' => '',
            'smtp_port' => 587,
            'smtp_user' => '',
            'smtp_pass' => '',
            'encryption' => 'tls',
        ],
    ];

    $fileConfig = [];
    if (is_file(GP_CONFIG)) {
        $loaded = require GP_CONFIG;
        if (is_array($loaded)) {
            $fileConfig = $loaded;
        }
    }

    $config = array_replace_recursive($defaults, $fileConfig);

    $envMap = [
        'GRAND_POPO_APP_KEY' => 'security.app_key',
        'GRAND_POPO_DB_PATH' => 'database.path',
        'GRAND_POPO_SESSION_NAME' => 'auth.session_name',
        'GRAND_POPO_ADMIN_PASSWORD' => 'auth.admin.default_password',
        'GRAND_POPO_CONTACT_EMAIL' => 'contact.email',
        'GRAND_POPO_CONTACT_PHONE' => 'contact.phone',
        'GRAND_POPO_SMTP_HOST' => 'mail.smtp_host',
        'GRAND_POPO_SMTP_USER' => 'mail.smtp_user',
        'GRAND_POPO_SMTP_PASS' => 'mail.smtp_pass',
    ];

    foreach ($envMap as $env => $key) {
        $value = getenv($env);
        if ($value === false || $value === '') {
            continue;
        }
        gp_config_set($config, $key, $value);
    }

    return $config;
}

function gp_config_set(array &$config, string $key, mixed $value): void
{
    $parts = array_values(array_filter(explode('.', $key), static fn($part): bool => $part !== ''));
    if ($parts === []) {
        return;
    }

    $cursor =& $config;
    foreach ($parts as $index => $part) {
        $isLast = $index === (count($parts) - 1);
        if ($isLast) {
            $cursor[$part] = $value;
            return;
        }

        if (!isset($cursor[$part]) || !is_array($cursor[$part])) {
            $cursor[$part] = [];
        }

        $cursor =& $cursor[$part];
    }
}

function gp_config(string $key = '', mixed $default = null): mixed
{
    $config = gp_config_all();
    if ($key === '') {
        return $config;
    }

    $cursor = $config;
    foreach (array_values(array_filter(explode('.', $key), static fn($part): bool => $part !== '')) as $part) {
        if (!is_array($cursor) || !array_key_exists($part, $cursor)) {
            return $default;
        }
        $cursor = $cursor[$part];
    }

    return $cursor;
}

function gp_data(): array
{
    static $data = null;
    if ($data !== null) {
        return $data;
    }

    if (!is_file(GP_DATA)) {
        throw new RuntimeException('Le fichier data/site-data.json est introuvable.');
    }

    $json = file_get_contents(GP_DATA);
    $data = json_decode($json ?: '[]', true, flags: JSON_THROW_ON_ERROR);
    return $data;
}

function gp_site_name(): string
{
    return (string) gp_config('app.name', 'Mairie de Grand-Popo');
}

function gp_site_url(): string
{
    $scheme = 'http';
    if (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') {
        $scheme = 'https';
    }
    $host = $_SERVER['HTTP_HOST'] ?? 'localhost';
    return $scheme . '://' . $host;
}

function gp_normalize_path(?string $path): string
{
    $path = rawurldecode($path ?? '/');
    $path = parse_url($path, PHP_URL_PATH) ?: '/';
    $path = '/' . ltrim($path, '/');
    if ($path !== '/' && str_ends_with($path, '/')) {
        $path = rtrim($path, '/');
    }
    return $path ?: '/';
}

