function gp_page_path(string $key): string
{
    if ($key !== '' && ($key[0] === '/' || $key[0] === '#')) {
        return $key;
    }
    foreach (gp_route_map() as $path => $routeKey) {
        if ($routeKey === $key) {
            return $path;
        }
    }

    return '/';
}

function gp_current_key(string $path): string
{
    return gp_route_map()[$path] ?? 'home';
}

function gp_route_url(string $key): string
{
    return gp_site_url() . gp_page_path($key);
}

function gp_excerpt(string $text, int $length = 160): string
{
    $text = trim(preg_replace('/\s+/', ' ', strip_tags($text)) ?? '');
    if (mb_strlen($text) <= $length) {
        return $text;
    }
    return rtrim(mb_substr($text, 0, $length - 1)) . '...';
}

function gp_h(string $value): string
{
    return htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}

