function gp_fix_simple_mojibake(string $text): string
{
    $text = trim($text);
    if ($text === '') {
        return '';
    }

    if (!gp_has_simple_mojibake($text)) {
        return $text;
    }

    $fixed = @iconv('UTF-8', 'Windows-1252//IGNORE', $text);
    if (is_string($fixed) && $fixed !== '') {
        $text = $fixed;
    }

    return trim(html_entity_decode($text, ENT_QUOTES | ENT_HTML5, 'UTF-8'));
}

function gp_services_catalog_sanitize(mixed $value): mixed
{
    if (is_array($value)) {
        foreach ($value as $key => $item) {
            $value[$key] = gp_services_catalog_sanitize($item);
        }

        return $value;
    }

    if (is_string($value)) {
        return gp_fix_simple_mojibake($value);
    }

    return $value;
}

function gp_services_catalog(): array
{
    static $catalog = null;
    if ($catalog !== null) {
        return $catalog;
    }

    if (!is_file(GP_SERVICES_CATALOG)) {
        $catalog = ['categories' => [], 'form' => []];
        return $catalog;
    }

    try {
        $json = (string) file_get_contents(GP_SERVICES_CATALOG);
        $decoded = json_decode($json ?: '[]', true, flags: JSON_THROW_ON_ERROR);
    } catch (Throwable $e) {
        $catalog = ['categories' => [], 'form' => []];
        return $catalog;
    }

    $catalog = is_array($decoded) ? gp_services_catalog_sanitize($decoded) : ['categories' => [], 'form' => []];

    $categories = array_values(array_filter((array) ($catalog['categories'] ?? []), static fn($item): bool => is_array($item)));
    foreach ($categories as &$category) {
        $services = array_values(array_filter((array) ($category['services'] ?? []), static fn($item): bool => is_array($item)));
        $category['services'] = $services;
        $category['count'] = count($services);
    }
    unset($category);

    $catalog['categories'] = $categories;
    $catalog['form'] = is_array($catalog['form'] ?? null) ? $catalog['form'] : [];

    return $catalog;
}

function gp_services_category(?string $slug): ?array
{
    $slug = trim((string) $slug);
    if ($slug === '') {
        return null;
    }

    foreach (gp_services_catalog()['categories'] as $category) {
        if ((string) ($category['slug'] ?? '') === $slug) {
            return $category;
        }
    }

    return null;
}

function gp_service_from_query(?string $categorySlug, ?string $serviceName): ?array
{
    $serviceName = trim((string) $serviceName);
    if ($serviceName === '') {
        return null;
    }

    $serviceNeedle = mb_strtolower($serviceName, 'UTF-8');
    $categories = gp_services_catalog()['categories'];

    if ($categorySlug !== null && trim($categorySlug) !== '') {
        $categories = array_values(array_filter($categories, static fn($category): bool => (string) ($category['slug'] ?? '') === trim((string) $categorySlug)));
    }

    foreach ($categories as $category) {
        foreach ((array) ($category['services'] ?? []) as $service) {
            $label = trim((string) ($service['name'] ?? $service['title'] ?? ''));
            if ($label === '') {
                continue;
            }

            if (mb_strtolower($label, 'UTF-8') === $serviceNeedle) {
                $service['category_slug'] = (string) ($category['slug'] ?? '');
                $service['category_label'] = (string) ($category['label'] ?? '');
                return $service;
            }
        }
    }

    return null;
}

function gp_db(): PDO
{
    static $pdo = null;
    if ($pdo instanceof PDO) {
        return $pdo;
    }

    if (!is_dir(GP_STORAGE)) {
        mkdir(GP_STORAGE, 0775, true);
    }

    $dbPath = (string) gp_config('database.path', GP_DB);
    if ($dbPath === '') {
        $dbPath = GP_DB;
    }

    $dbDir = dirname($dbPath);
    if (!is_dir($dbDir)) {
        mkdir($dbDir, 0775, true);
    }

    $pdo = new PDO('sqlite:' . $dbPath, null, null, [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
    ]);
    $pdo->exec('PRAGMA foreign_keys = ON');
    gp_bootstrap_db($pdo);
    return $pdo;
}

function gp_bootstrap_db(PDO $pdo): void
{
    $pdo->exec(
        'CREATE TABLE IF NOT EXISTS settings (
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL
        )'
    );
    $pdo->exec(
        'CREATE TABLE IF NOT EXISTS hero_slides (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            subtitle TEXT NOT NULL,
            image TEXT NOT NULL,
            cta_label TEXT NOT NULL,
            cta_url TEXT NOT NULL,
            accent TEXT NOT NULL DEFAULT "#0a2540",
            sort_order INTEGER NOT NULL DEFAULT 0,
            is_active INTEGER NOT NULL DEFAULT 1,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        )'
    );
    $pdo->exec(
        'CREATE TABLE IF NOT EXISTS admins (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL UNIQUE,
            password_hash TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        )'
    );
    $pdo->exec(
        'CREATE TABLE IF NOT EXISTS inquiries (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            kind TEXT NOT NULL,
            payload TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        )'
    );
    $pdo->exec(
        'CREATE TABLE IF NOT EXISTS page_overrides (
            page_key TEXT PRIMARY KEY,
            title TEXT NULL,
            lead TEXT NULL,
            image TEXT NULL,
            custom_html TEXT NULL,
            seo_title TEXT NULL,
            seo_description TEXT NULL,
            show_form INTEGER NULL,
            updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        )'
    );
    $pdo->exec(
        'CREATE TABLE IF NOT EXISTS blog_posts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            wp_id INTEGER NOT NULL UNIQUE,
            slug TEXT NOT NULL UNIQUE,
            title TEXT NOT NULL,
            excerpt TEXT NOT NULL,
            content TEXT NOT NULL,
            image TEXT NULL,
            source_url TEXT NULL,
            published_at TEXT NULL,
            updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        )'
    );
    $pdo->exec(
        'CREATE TABLE IF NOT EXISTS forum_users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL UNIQUE,
            email TEXT NOT NULL UNIQUE,
            password_hash TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        )'
    );
    $pdo->exec(
        'CREATE TABLE IF NOT EXISTS forum_topics (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            title TEXT NOT NULL,
            body TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (user_id) REFERENCES forum_users(id) ON DELETE CASCADE
        )'
    );
    $pdo->exec(
        'CREATE TABLE IF NOT EXISTS forum_posts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            topic_id INTEGER NOT NULL,
            user_id INTEGER NOT NULL,
            body TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (topic_id) REFERENCES forum_topics(id) ON DELETE CASCADE,
            FOREIGN KEY (user_id) REFERENCES forum_users(id) ON DELETE CASCADE
        )'
    );
    $pdo->exec('CREATE INDEX IF NOT EXISTS idx_forum_topics_user ON forum_topics(user_id)');
    $pdo->exec('CREATE INDEX IF NOT EXISTS idx_forum_posts_topic ON forum_posts(topic_id)');
    $pdo->exec('CREATE INDEX IF NOT EXISTS idx_forum_posts_user ON forum_posts(user_id)');
    gp_seed_setting($pdo, 'hero_kicker', 'Portail officiel 2026');
    gp_seed_setting($pdo, 'hero_title', 'Bienvenue a Grand-Popo, la cite balneaire du Benin');
    gp_seed_setting($pdo, 'hero_lead', 'La mairie de Grand-Popo digitalise vos demarches, valorise son patrimoine et rapproche les services publics des citoyens.');
    gp_seed_setting($pdo, 'hero_primary_label', "Acceder a l'e-guichet");
    gp_seed_setting($pdo, 'hero_primary_url', '/demarches/etat-civil');
    gp_seed_setting($pdo, 'hero_secondary_label', 'Decouvrir la commune');
    gp_seed_setting($pdo, 'hero_secondary_url', '/commune/presentation');
    gp_seed_setting($pdo, 'site_notice', 'Grand-Popo, cite balneaire du Sud-Ouest beninois');

    $count = (int) $pdo->query('SELECT COUNT(*) AS c FROM hero_slides')->fetch()['c'];
    if ($count === 0) {
        $slides = gp_default_hero_slides();
        $stmt = $pdo->prepare('INSERT INTO hero_slides (title, subtitle, image, cta_label, cta_url, accent, sort_order, is_active) VALUES (:title, :subtitle, :image, :cta_label, :cta_url, :accent, :sort_order, :is_active)');
        foreach ($slides as $i => $slide) {
            $stmt->execute([
                ':title' => $slide['title'],
                ':subtitle' => $slide['subtitle'],
                ':image' => $slide['image'],
                ':cta_label' => $slide['cta_label'],
                ':cta_url' => $slide['cta_url'],
                ':accent' => $slide['accent'],
                ':sort_order' => $i + 1,
                ':is_active' => 1,
            ]);
        }
    }

    $adminCount = (int) $pdo->query('SELECT COUNT(*) AS c FROM admins')->fetch()['c'];
    if ($adminCount === 0) {
        $adminUsername = trim((string) gp_config('auth.admin.default_username', 'admin'));
        if ($adminUsername === '') {
            $adminUsername = 'admin';
        }

        $password = (string) gp_config('auth.admin.default_password', 'grand-popo');
        if ($password === '') {
            $password = 'grand-popo';
        }

        $pdo->prepare('INSERT INTO admins (username, password_hash) VALUES (?, ?)')->execute([
            $adminUsername,
            password_hash($password, PASSWORD_DEFAULT),
        ]);
    }
}

function gp_seed_setting(PDO $pdo, string $key, string $value): void
{
    $stmt = $pdo->prepare('INSERT OR IGNORE INTO settings (key, value) VALUES (?, ?)');
    $stmt->execute([$key, $value]);
}

function gp_setting(string $key, ?string $fallback = null): ?string
{
    $stmt = gp_db()->prepare('SELECT value FROM settings WHERE key = ?');
    $stmt->execute([$key]);
    $row = $stmt->fetch();
    return $row['value'] ?? $fallback;
}

function gp_update_setting(string $key, string $value): void
{
    $stmt = gp_db()->prepare('INSERT INTO settings (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value');
    $stmt->execute([$key, $value]);
}

