function gp_default_home_hero_slides_text(): string
{
    $blocks = [];
    foreach (gp_default_home_hero_slide_blocks() as $block) {
        $blocks[] = implode("
", [
            'title: ' . $block['title'],
            'subtitle: ' . $block['subtitle'],
            'desc: ' . $block['desc'],
        ]);
    }
    return implode("

---

", $blocks) . "
";
}

function gp_save_home_hero_slides_text(string $text): void
{
    $path = gp_home_hero_slides_path();
    $text = trim(str_replace(["\r\n", "\r"], "\n", $text));
    if ($text === '') {
        $text = trim(gp_default_home_hero_slides_text());
    }
    file_put_contents($path, $text . "\n", LOCK_EX);
}

function gp_home_hero_slides_text(): string
{
    $path = gp_home_hero_slides_path();
    if (!is_file($path) || trim((string) @file_get_contents($path)) === '') {
        gp_save_home_hero_slides_text(gp_default_home_hero_slides_text());
    }
    return (string) @file_get_contents($path);
}

function gp_parse_home_hero_slides_text(string $text): array
{
    $text = trim($text);
    if ($text === '') {
        return [];
    }

    $blocks = preg_split('/^\s*---\s*$/m', $text) ?: [];
    $slides = [];
    foreach ($blocks as $block) {
        $slide = ['title' => '', 'subtitle' => '', 'desc' => ''];
        foreach (preg_split('/\R/', trim($block)) ?: [] as $line) {
            if (preg_match('/^(title|subtitle|desc)\s*:\s*(.+)$/i', trim($line), $match)) {
                $slide[strtolower($match[1])] = trim($match[2]);
            }
        }
        if ($slide['title'] !== '' || $slide['subtitle'] !== '' || $slide['desc'] !== '') {
            $slides[] = $slide;
        }
    }
    return $slides;
}

function gp_home_hero_slides(): array
{
    $images = ['/assets/slides/Slide1.png', '/assets/slides/Slide2.png', '/assets/slides/Slide3.png'];
    $parsed = gp_parse_home_hero_slides_text(gp_home_hero_slides_text());
    $defaults = gp_default_home_hero_slide_blocks();
    $slides = [];

    foreach ($images as $index => $image) {
        $block = $parsed[$index] ?? $defaults[$index] ?? ['title' => '', 'subtitle' => '', 'desc' => ''];
        $slides[] = [
            'image' => $image,
            'title' => $block['title'] ?? '',
            'subtitle' => $block['subtitle'] ?? '',
            'desc' => $block['desc'] ?? '',
        ];
    }

    return $slides;
}

function gp_default_ticker_items(): array
{
    $items = gp_data()['TICKER'] ?? [];
    $items = array_values(array_filter(array_map(static fn($item) => trim((string) $item), is_array($items) ? $items : []), static fn($item) => $item !== ''));
    return $items ?: ['Portail officiel de la commune de Grand-Popo'];
}

function gp_parse_ticker_items(string $value): array
{
    $value = trim(str_replace(["\r\n", "\r"], "\n", $value));
    if ($value === '') {
        return [];
    }

    $items = preg_split('/\n+/', $value) ?: [];
    $clean = [];
    foreach ($items as $item) {
        $item = trim(preg_replace('/^[?\-*]+\s*/u', '', (string) $item) ?? '');
        if ($item !== '') {
            $clean[] = $item;
        }
    }
    return array_values(array_unique($clean));
}

function gp_ticker_items(): array
{
    $raw = gp_setting('ticker_items', '');
    $items = gp_parse_ticker_items((string) $raw);
    return $items ?: gp_default_ticker_items();
}

function gp_hero_slides(bool $activeOnly = true): array
{
    $sql = 'SELECT * FROM hero_slides';
    if ($activeOnly) {
        $sql .= ' WHERE is_active = 1';
    }
    $sql .= ' ORDER BY sort_order ASC, id ASC';
    return gp_db()->query($sql)->fetchAll();
}

function gp_page_overrides(): array
{
    $rows = gp_db()->query('SELECT * FROM page_overrides ORDER BY page_key ASC')->fetchAll();
    $out = [];
    foreach ($rows as $row) {
        $out[$row['page_key']] = $row;
    }
    return $out;
}

function gp_page_override(string $key): ?array
{
    $stmt = gp_db()->prepare('SELECT * FROM page_overrides WHERE page_key = ?');
    $stmt->execute([$key]);
    $row = $stmt->fetch();
    return $row ?: null;
}

function gp_save_page_override(string $key, array $data): void
{
    $stmt = gp_db()->prepare('INSERT INTO page_overrides (page_key, title, lead, image, custom_html, seo_title, seo_description, show_form, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP) ON CONFLICT(page_key) DO UPDATE SET title = excluded.title, lead = excluded.lead, image = excluded.image, custom_html = excluded.custom_html, seo_title = excluded.seo_title, seo_description = excluded.seo_description, show_form = excluded.show_form, updated_at = CURRENT_TIMESTAMP');
    $stmt->execute([
        $key,
        $data['title'] ?? null,
        $data['lead'] ?? null,
        $data['image'] ?? null,
        $data['custom_html'] ?? null,
        $data['seo_title'] ?? null,
        $data['seo_description'] ?? null,
        array_key_exists('show_form', $data) ? $data['show_form'] : null,
    ]);
}

function gp_delete_page_override(string $key): void
{
    gp_db()->prepare('DELETE FROM page_overrides WHERE page_key = ?')->execute([$key]);
}

