function gp_admin_user(): ?array
{
    gp_boot_session();
    if (empty($_SESSION['gp_admin_id'])) {
        return null;
    }
    $stmt = gp_db()->prepare('SELECT id, username FROM admins WHERE id = ?');
    $stmt->execute([(int) $_SESSION['gp_admin_id']]);
    $admin = $stmt->fetch();
    return $admin ?: null;
}

function gp_admin_login(string $username, string $password): bool
{
    gp_boot_session();
    $stmt = gp_db()->prepare('SELECT * FROM admins WHERE username = ?');
    $stmt->execute([$username]);
    $admin = $stmt->fetch();
    if (!$admin || !password_verify($password, $admin['password_hash'])) {
        return false;
    }
    $_SESSION['gp_admin_id'] = (int) $admin['id'];
    $_SESSION['gp_admin_user'] = $admin['username'];
    return true;
}

function gp_admin_logout(): void
{
    gp_boot_session();
    unset($_SESSION['gp_admin_id'], $_SESSION['gp_admin_user']);
}

function gp_csrf_token(): string
{
    gp_boot_session();
    if (empty($_SESSION['gp_csrf'])) {
        $_SESSION['gp_csrf'] = bin2hex(random_bytes(16));
    }
    return $_SESSION['gp_csrf'];
}

function gp_verify_csrf(?string $token): bool
{
    gp_boot_session();
    return is_string($token) && isset($_SESSION['gp_csrf']) && hash_equals($_SESSION['gp_csrf'], $token);
}

function gp_request_path(): string
{
    return gp_normalize_path($_SERVER['REQUEST_URI'] ?? '/');
}

function gp_public_upload(array $file, string $folder = 'uploads/hero'): ?string
{
    if (!isset($file['error']) || $file['error'] === UPLOAD_ERR_NO_FILE) {
        return null;
    }

    if ($file['error'] !== UPLOAD_ERR_OK) {
        throw new RuntimeException('Upload failed.');
    }

    $tmp = (string) ($file['tmp_name'] ?? '');
    if ($tmp === '' || !is_uploaded_file($tmp)) {
        throw new RuntimeException('Invalid upload.');
    }

    if ((int) ($file['size'] ?? 0) > 8 * 1024 * 1024) {
        throw new RuntimeException('Image too large.');
    }

    $finfo = new finfo(FILEINFO_MIME_TYPE);
    $mime = $finfo->file($tmp) ?: '';
    $map = [
        'image/jpeg' => 'jpg',
        'image/png' => 'png',
        'image/webp' => 'webp',
        'image/gif' => 'gif',
    ];

    if (!isset($map[$mime])) {
        throw new RuntimeException('Unsupported image type.');
    }

    $folder = trim($folder, '/');
    $dir = GP_ROOT . '/' . $folder;
    if (!is_dir($dir) && !mkdir($dir, 0775, true) && !is_dir($dir)) {
        throw new RuntimeException('Cannot create upload directory.');
    }

    $name = 'slide-' . date('YmdHis') . '-' . bin2hex(random_bytes(4)) . '.' . $map[$mime];
    $target = $dir . '/' . $name;
    if (!move_uploaded_file($tmp, $target)) {
        throw new RuntimeException('Could not save upload.');
    }

    return '/' . $folder . '/' . $name;
}


