            }
            if ($image === '') {
                $image = (string) (gp_extract_image_from_html($contentHtml) ?? '');
            }
            if ($image !== '' && str_starts_with($image, '//')) {
                $image = 'https:' . $image;
            }

            $stmt->execute([
                ':wp_id' => $wpId,
                ':slug' => $slug,
