                ':image' => $image !== '' ? $image : null,
                ':source_url' => (string) ($item['link'] ?? ''),
                ':published_at' => (string) ($item['date'] ?? ''),
            ]);

            $total++;
        }

        if (count($items) < $perPage) {
            break;
        }
    }

    if ($total > 0 || $count > 0) {
        gp_update_setting('blog_last_sync', date(DATE_ATOM));
    }

    return (int) gp_db()->query('SELECT COUNT(*) AS c FROM blog_posts')->fetch()['c'];
}

function gp_blog_posts(int $limit = 12, int $offset = 0): array
{
    $limit = max(1, min(100, $limit));
    $offset = max(0, $offset);

    $stmt = gp_db()->prepare('SELECT * FROM blog_posts ORDER BY datetime(published_at) DESC, id DESC LIMIT :limit OFFSET :offset');
    $stmt->bindValue(':limit', $limit, PDO::PARAM_INT);
    $stmt->bindValue(':offset', $offset, PDO::PARAM_INT);
    $stmt->execute();

    return $stmt->fetchAll() ?: [];
}

function gp_blog_post_by_slug(string $slug): ?array
{
    $stmt = gp_db()->prepare('SELECT * FROM blog_posts WHERE slug = ? LIMIT 1');
    $stmt->execute([$slug]);
    $row = $stmt->fetch();

    return $row ?: null;
}

function gp_blog_has_posts(): bool
{
    $row = gp_db()->query('SELECT COUNT(*) AS c FROM blog_posts')->fetch();
    return ((int) ($row['c'] ?? 0)) > 0;
}


















function gp_boot_session(): void
{
    if (session_status() === PHP_SESSION_ACTIVE) {
        return;
    }

    $sessionName = trim((string) gp_config('auth.session_name', 'grand_popo_session'));
    if ($sessionName !== '') {
        session_name($sessionName);
    }

    $lifetime = (int) gp_config('auth.session_lifetime', 86400);
    if ($lifetime <= 0) {
        $lifetime = 86400;
    }

    $isHttps = !empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off';
    session_set_cookie_params([
        'lifetime' => $lifetime,
        'path' => '/',
        'domain' => '',
        'secure' => $isHttps,
        'httponly' => true,
        'samesite' => 'Lax',
    ]);

    session_start();
}

function gp_flash_set(string $scope, string $message, string $type = 'success'): void
{
    gp_boot_session();
    $_SESSION['gp_flash'][$scope] = [
        'type' => $type,
        'message' => trim($message),
    ];
}

function gp_flash_get(string $scope): ?array
{
    gp_boot_session();
    if (empty($_SESSION['gp_flash'][$scope]) || !is_array($_SESSION['gp_flash'][$scope])) {
        return null;
    }

    $flash = $_SESSION['gp_flash'][$scope];
    unset($_SESSION['gp_flash'][$scope]);

    return $flash;
}

function gp_forum_registration_enabled(): bool
{
    return (bool) gp_config('forum.registration.enabled', true);
}

function gp_forum_min_password_length(): int
{
    $length = (int) gp_config('forum.registration.min_password_length', 8);
    return max(6, min(32, $length));
}

function gp_forum_default_redirect(): string
{
    $path = trim((string) gp_config('forum.default_redirect', '/forums-de-discussion'));
    if ($path === '' || !str_starts_with($path, '/') || str_starts_with($path, '//')) {
        return '/forums-de-discussion';
    }

    return $path;
}

function gp_forum_session_key(): string
{
    return 'gp_forum_user_id';
}

function gp_forum_normalize_text(string $value): string
{
    $value = str_replace(["\r\n", "\r"], "\n", $value);
    $value = preg_replace('/[\t ]+/', ' ', $value) ?? $value;
    $value = preg_replace("/\n{3,}/", "\n\n", $value) ?? $value;
    return trim($value);
}

function gp_forum_user_by_id(int $id): ?array
{
    if ($id <= 0) {
        return null;
    }

    $stmt = gp_db()->prepare('SELECT id, username, email, created_at FROM forum_users WHERE id = ? LIMIT 1');
    $stmt->execute([$id]);
    $row = $stmt->fetch();

    return $row ?: null;
}

function gp_forum_user(): ?array
{
    gp_boot_session();
    $key = gp_forum_session_key();
    $id = (int) ($_SESSION[$key] ?? 0);
    if ($id <= 0) {
        return null;
    }

    $user = gp_forum_user_by_id($id);
    if (!$user) {
        unset($_SESSION[$key]);
        return null;
    }

    return $user;
}

function gp_forum_login(string $identifier, string $password): bool
{
    $identifier = trim($identifier);
    if ($identifier === '' || $password === '') {
        return false;
    }

    $stmt = gp_db()->prepare('SELECT * FROM forum_users WHERE lower(username) = lower(?) OR lower(email) = lower(?) LIMIT 1');
    $stmt->execute([$identifier, $identifier]);
    $user = $stmt->fetch();

    if (!$user || !password_verify($password, (string) $user['password_hash'])) {
        return false;
    }

    gp_boot_session();
    $_SESSION[gp_forum_session_key()] = (int) $user['id'];

    return true;
}

function gp_forum_logout(): void
{
    gp_boot_session();
    unset($_SESSION[gp_forum_session_key()]);
}

function gp_forum_register(string $username, string $email, string $password): array
{
    $username = trim($username);
    $email = trim($email);

    if (!gp_forum_registration_enabled()) {
        return ['ok' => false, 'error' => 'Les inscriptions sont temporairement fermees.'];
    }

    if ($username === '' || mb_strlen($username) < 3) {
        return ['ok' => false, 'error' => 'Identifiant trop court (3 caracteres minimum).'];
    }

    if (!preg_match('/^[A-Za-z0-9._-]+$/', $username)) {
        return ['ok' => false, 'error' => 'Identifiant invalide. Utilisez lettres, chiffres, point, tiret ou underscore.'];
    }

    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return ['ok' => false, 'error' => 'Adresse email invalide.'];
    }

    if (mb_strlen($password) < gp_forum_min_password_length()) {
        return ['ok' => false, 'error' => 'Mot de passe trop court.'];
    }

    $db = gp_db();
    $check = $db->prepare('SELECT id FROM forum_users WHERE lower(username) = lower(?) OR lower(email) = lower(?) LIMIT 1');
    $check->execute([$username, $email]);
    if ($check->fetch()) {
        return ['ok' => false, 'error' => 'Cet identifiant ou cet email est deja utilise.'];
    }

    $stmt = $db->prepare('INSERT INTO forum_users (username, email, password_hash) VALUES (?, ?, ?)');
    $stmt->execute([
        $username,
        $email,
        password_hash($password, PASSWORD_DEFAULT),
    ]);

    $id = (int) $db->lastInsertId();
    if ($id <= 0) {
        return ['ok' => false, 'error' => 'Inscription impossible pour le moment.'];
    }

    gp_boot_session();
    $_SESSION[gp_forum_session_key()] = $id;

    return ['ok' => true, 'user_id' => $id, 'error' => ''];
}

function gp_forum_total_counts(): array
{
    $db = gp_db();
    $topics = (int) ($db->query('SELECT COUNT(*) AS c FROM forum_topics')->fetch()['c'] ?? 0);
    $messages = (int) ($db->query('SELECT COUNT(*) AS c FROM forum_posts')->fetch()['c'] ?? 0);

    return [
        'topics' => $topics,
        'messages' => $messages,
    ];
}

function gp_forum_topics(int $limit = 40): array
{
    $limit = max(1, min(100, $limit));

    $stmt = gp_db()->prepare(
        'SELECT
            t.id,
            t.title,
            t.body,
            t.created_at,
            t.updated_at,
            u.username AS author_name,
            COUNT(p.id) AS replies_count,
            MAX(p.created_at) AS last_reply_at
        FROM forum_topics t
        INNER JOIN forum_users u ON u.id = t.user_id
        LEFT JOIN forum_posts p ON p.topic_id = t.id
        GROUP BY t.id, t.title, t.body, t.created_at, t.updated_at, u.username
        ORDER BY COALESCE(MAX(p.created_at), t.created_at) DESC, t.id DESC
        LIMIT :limit'
    );
    $stmt->bindValue(':limit', $limit, PDO::PARAM_INT);
    $stmt->execute();

    return $stmt->fetchAll() ?: [];
}

function gp_forum_topic(int $id): ?array
{
    if ($id <= 0) {
        return null;
    }

    $stmt = gp_db()->prepare(
        'SELECT
            t.id,
            t.user_id,
            t.title,
            t.body,
            t.created_at,
            t.updated_at,
            u.username AS author_name,
            u.email AS author_email
         FROM forum_topics t
         INNER JOIN forum_users u ON u.id = t.user_id
         WHERE t.id = ?
         LIMIT 1'
    );
    $stmt->execute([$id]);
    $topic = $stmt->fetch();
    if (!$topic) {
        return null;
    }

    $postsStmt = gp_db()->prepare(
        'SELECT p.id, p.topic_id, p.user_id, p.body, p.created_at, u.username AS author_name
         FROM forum_posts p
         INNER JOIN forum_users u ON u.id = p.user_id
         WHERE p.topic_id = ?
         ORDER BY p.created_at ASC, p.id ASC'
    );
    $postsStmt->execute([$id]);
    $topic['posts'] = $postsStmt->fetchAll() ?: [];
    $topic['replies_count'] = count((array) $topic['posts']);

    return $topic;
}

function gp_forum_create_topic(int $userId, string $title, string $body): int
{
    if ($userId <= 0) {
        return 0;
    }

    $title = gp_forum_normalize_text($title);
    $body = gp_forum_normalize_text($body);

    if ($title === '' || mb_strlen($title) < 6 || $body === '' || mb_strlen($body) < 10) {
        return 0;
    }

    $db = gp_db();
    $stmt = $db->prepare('INSERT INTO forum_topics (user_id, title, body, created_at, updated_at) VALUES (?, ?, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)');
    $stmt->execute([$userId, $title, $body]);

    return (int) $db->lastInsertId();
}

function gp_forum_add_post(int $topicId, int $userId, string $body): bool
{
    if ($topicId <= 0 || $userId <= 0) {
        return false;
    }

    $body = gp_forum_normalize_text($body);
    if ($body === '' || mb_strlen($body) < 2) {
        return false;
    }

    $db = gp_db();
    $check = $db->prepare('SELECT id FROM forum_topics WHERE id = ? LIMIT 1');
    $check->execute([$topicId]);
    if (!$check->fetch()) {
        return false;
    }

    $stmt = $db->prepare('INSERT INTO forum_posts (topic_id, user_id, body, created_at) VALUES (?, ?, ?, CURRENT_TIMESTAMP)');
    $stmt->execute([$topicId, $userId, $body]);

    $db->prepare('UPDATE forum_topics SET updated_at = CURRENT_TIMESTAMP WHERE id = ?')->execute([$topicId]);

    return true;
}

function gp_forum_sanitize_redirect(?string $target, ?string $fallback = null): string
{
    $fallback = $fallback ?: gp_forum_default_redirect();
    $target = trim((string) $target);

    if ($target === '') {
        return $fallback;
    }

    if (preg_match('#^https?://#i', $target)) {
        return $fallback;
    }

    if (!str_starts_with($target, '/') || str_starts_with($target, '//')) {
        return $fallback;
    }

    return $target;
}







